package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Build the ping command
	// -c: count of packets to send
	// -W: timeout in seconds for each packet (optional, but good practice)
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w, output: %s", err, string(output))
	}

	// Parse the output to extract round-trip time statistics
	// Example output line: "rtt min/avg/max/mdev = 1.234/5.678/9.012/1.234 ms"
	re := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches := re.FindStringSubmatch(string(output))
	if len(matches) < 2 {
		// Try alternative format for some systems or if only one ping was sent
		// Some systems might output differently, let's try to parse individual lines if needed
		// But typically, the summary line is standard on Linux/macOS

		// Fallback: try to parse individual reply lines if summary is missing
		// This is less reliable but handles edge cases
		lines := strings.Split(string(output), "\n")
		var totalLatency float64
		var validPings int

		replyRe := regexp.MustCompile(`time=([\d.]+)\s*ms`)
		for _, line := range lines {
			if match := replyRe.FindStringSubmatch(line); len(match) > 1 {
				latency, err := strconv.ParseFloat(match[1], 64)
				if err == nil {
					totalLatency += latency
					validPings++
				}
			}
		}

		if validPings == 0 {
			return 0, fmt.Errorf("could not parse latency from ping output: %s", string(output))
		}

		return totalLatency / float64(validPings), nil
	}

	avgStr := matches[1]
	avgLatency, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avgLatency, nil
}

func main() {
