package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %w, output: %s", err, string(output))
	}

	outputStr := string(output)

	// Try to parse the average latency from the ping output
	// Typical Linux ping output summary line:
	// rtt min/avg/max/mdev = 0.123/0.456/0.789/0.100 ms
	re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+`)
	matches := re.FindStringSubmatch(outputStr)
	if len(matches) >= 2 {
		avg, err := strconv.ParseFloat(matches[1], 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Alternative pattern for some systems or if packets were lost
	// Try parsing individual reply lines and calculate average manually
	reReply := regexp.MustCompile(`time=([\d.]+)\s*ms`)
	replyMatches := reReply.FindAllStringSubmatch(outputStr, -1)
	if len(replyMatches) > 0 {
		var total float64
		for _, match := range replyMatches {
			if len(match) >= 2 {
				val, err := strconv.ParseFloat(match[1], 64)
				if err != nil {
					continue
				}
				total += val
			}
		}
		if len(replyMatches) > 0 {
			return total / float64(len(replyMatches)), nil
		}
	}

	// Check if there's any packet loss indication
	if strings.Contains(outputStr, "100% packet loss") {
		return 0, fmt.Errorf("100%% packet loss")
	}

	return 0, fmt.Errorf("could not parse ping output: %s", outputStr)
}

func main() {
	// Example usage
	host := "8.8.8.8"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.2f ms\n", host, count, avgLatency)
}

