package main

import (
	"errors"
	"fmt"
	"net"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Validate that the host is a valid IP address or hostname to prevent command injection
	// We allow hostnames by resolving them first, but we strictly validate the input format
	// to ensure no shell metacharacters are present.
	if !isValidHost(host) {
		return 0, errors.New("invalid host format")
	}

	// Use exec.Command directly with arguments instead of bash -c to avoid shell injection
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w (output: %s)", err, string(output))
	}

	// Look for the line containing RTT statistics
	outputStr := string(output)
	lines := strings.Split(outputStr, "\n")
	var statsLine string
	for _, line := range lines {
		if strings.Contains(line, "rtt min/avg/max") {
			statsLine = line
			break
		}
	}

	if statsLine == "" {
		return 0, errors.New("could not find RTT statistics in ping output")
	}

	// Extract average latency using regex
	// Example line: rtt min/avg/max/mdev = 12.345/23.456/34.567/5.678 ms
	re := regexp.MustCompile(`rtt min/avg/max/mdev = \d+\.\d+/([\d.]+)/\d+\.\d+/\d+\.\d+ ms`)
	matches := re.FindStringSubmatch(statsLine)
	if len(matches) < 2 {
		return 0, errors.New("failed to parse average latency from ping output")
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert average latency to float: %w", err)
	}

	return avg, nil
}

// isValidHost checks if the host string contains only valid characters for a hostname or IP address.
// This prevents command injection attacks by ensuring no shell metacharacters are present.
func isValidHost(host string) bool {
	// Check if it's a valid IP address
	if ip := net.ParseIP(host); ip != nil {
		return true
	}

	// Check if it's a valid hostname
	// Hostnames can contain letters, digits, hyphens, and dots
	// They cannot start or end with a hyphen or dot
	// Each label must be between 1 and 63 characters
	// Total length must be less than 253 characters
	if len(host) > 253 || len(host) == 0 {
		return false
	}

	// Check each character
	for _, ch := range host {
		if !((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '-' || ch == '.') {
			return false
		}
	}

	// Additional validation: split by dots and check each part
	parts := strings.Split(host, ".")
	for _, part := range parts {
		if len(part) == 0 || len(part) > 63 {
			return false
		}
		if part[0] == '-' || part[len(part)-1] == '-' {
			return false
		}
	}

	return true
}

