package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %v, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	avgLatency, err := parseAverageLatency(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %v", err)
	}

	return avgLatency, nil
}

// parseAverageLatency extracts the average latency from the ping command output.
func parseAverageLatency(output string) (float64, error) {
	// Look for the line containing "rtt min/avg/max/mdev" or similar
	lines := strings.Split(output, "\n")
	for _, line := range lines {
		if strings.Contains(line, "rtt") || strings.Contains(line, "round-trip") {
			// Example format: rtt min/avg/max/mdev = 10.234/15.678/20.123/3.456 ms
			re := regexp.MustCompile(`= ([\d.]+)/([\d.]+)/([\d.]+)/([\d.]+)`)
			matches := re.FindStringSubmatch(line)
			if len(matches) >= 3 {
				avgStr := matches[2]
				avg, err := strconv.ParseFloat(avgStr, 64)
				if err != nil {
					return 0, fmt.Errorf("failed to parse average latency value: %v", err)
				}
				return avg, nil
			}
		}
	}

	return 0, fmt.Errorf("could not find average latency in ping output")
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.3f ms\n", host, avgLatency)
}

