package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w, output: %s", err, string(output))
	}

	// Parse the output to extract latency values
	// Example line from ping output on Linux:
	// 64 bytes from 8.8.8.8: icmp_seq=1 ttl=117 time=14.2 ms
	re := regexp.MustCompile(`time=([0-9]+\.?[0-9]*)\s*ms`)
	matches := re.FindAllStringSubmatch(string(output), -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	var totalLatency float64
	for _, match := range matches {
		latencyStr := match[1]
		latency, err := strconv.ParseFloat(latencyStr, 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse latency value '%s': %w", latencyStr, err)
		}
		totalLatency += latency
	}

	averageLatency := totalLatency / float64(len(matches))
	return averageLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

