package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command
	// On Linux/macOS: ping -c <count> <host>
	// We'll use -c for count which is standard on most Unix-like systems
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	// Typical output contains a line like:
	// rtt min/avg/max/mdev = 1.234/5.678/9.012/1.234 ms
	// or on some systems:
	// round-trip min/avg/max/stddev = 1.234/5.678/9.012/1.234 ms

	re := regexp.MustCompile(`rtt\s+min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(string(output))

	if len(matches) < 2 {
		// Try alternative format
		reAlt := regexp.MustCompile(`round-trip\s+min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
		matches = reAlt.FindStringSubmatch(string(output))
	}

	if len(matches) < 2 {
		// Try another common format without mdev/stddev
		reSimple := regexp.MustCompile(`rtt\s+min/avg/max\s*=\s*[\d.]+/([\d.]+)/[\d.]+\s*ms`)
		matches = reSimple.FindStringSubmatch(string(output))
	}

	if len(matches) < 2 {
		return 0, fmt.Errorf("could not parse ping output: %s", strings.TrimSpace(string(output)))
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %v", err)
	}

	return avg, nil
}

func main() {
	host := "google.com"
	count := 3

	fmt.Printf("Pinging %s %d times...\n", host, count)
	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency: %.3f ms\n", latency)
}

