package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Build the ping command arguments
	// -c: count (number of packets to send)
	args := []string{"-c", strconv.Itoa(count), host}

	cmd := exec.Command("ping", args...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w, output: %s", err, string(output))
	}

	outputStr := string(output)

	// Parse the output to extract the average latency
	// The format varies by OS, but typically includes something like:
	// Linux: rtt min/avg/max/mdev = 1.234/5.678/9.012/3.456 ms
	// macOS: round-trip min/avg/max/stddev = 1.234/5.678/9.012/3.456 ms

	// Try to match the avg value from the summary line
	re := regexp.MustCompile(`rtt\s+min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(outputStr)

	if len(matches) > 1 {
		avgStr := matches[1]
		avg, err := strconv.ParseFloat(avgStr, 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Try macOS format: round-trip min/avg/max/stddev
	reMac := regexp.MustCompile(`round-trip\s+min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matchesMac := reMac.FindStringSubmatch(outputStr)

	if len(matchesMac) > 1 {
		avgStr := matchesMac[1]
		avg, err := strconv.ParseFloat(avgStr, 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Fallback: try to find individual time values and calculate average
	// Look for patterns like "time=1.234 ms" or "time=1.234ms"
	timeRe := regexp.MustCompile(`time=([\d.]+)\s*ms`)
	timeMatches := timeRe.FindAllStringSubmatch(outputStr, -1)

	if len(timeMatches) == 0 {
		return 0, fmt.Errorf("could not parse ping output: %s", outputStr)
	}

	var total float64
	for _, match := range timeMatches {
		t, err := strconv.ParseFloat(match[1], 64)
		if err != nil {
			continue
		}
		total += t
	}

	if len(timeMatches) == 0 {
		return 0, fmt.Errorf("no valid time values found in ping output")
	}

	avg := total / float64(len(timeMatches))
	return avg, nil
}

func main() {
	host := "localhost"
	count := 4

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d pings: %.3f ms\n", host, count, avgLatency)
}

