import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w, output: %s", err, string(output))
	}

	// Parse the output to extract round-trip time statistics
	// Typical Linux ping output ends with something like:
	// rtt min/avg/max/mdev = 1.234/5.678/9.012/3.456 ms
	re := regexp.MustCompile(`rtt min/avg/max/mdev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
	matches := re.FindStringSubmatch(string(output))
	if len(matches) < 2 {
		// Try alternative format for macOS/BSD
		reMac := regexp.MustCompile(`round-trip min/avg/max/stddev = [\d.]+/([\d.]+)/[\d.]+/[\d.]+ ms`)
		matches = reMac.FindStringSubmatch(string(output))
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not parse ping output: %s", string(output))
		}
	}

	avgStr := matches[1]
	avgLatency, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avgLatency, nil
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", latency)
}

