		matches = reMac.FindStringSubmatch(outputStr)
		if len(matches) < 2 {
			return 0, fmt.Errorf("could not parse average latency from ping output: %s", outputStr)
		}
	}

	avgStr := matches[1]
	avgLatency, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avgLatency, nil
}

func main() {
