// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w, output: %s", err, string(output))
	}

	// Parse the output to extract latency values
	latencies, err := parsePingOutput(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	if len(latencies) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	// Calculate average latency
	var total float64
	for _, l := range latencies {
		total += l
	}
	average := total / float64(len(latencies))

	return average, nil
}

// parsePingOutput extracts individual latency values from the ping command output.
func parsePingOutput(output string) ([]float64, error) {
	var latencies []float64

	// Match lines like "64 bytes from ... time=12.3 ms"
	re := regexp.MustCompile(`time=(\d+\.?\d*)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	for _, match := range matches {
		if len(match) >= 2 {
			latency, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue // Skip invalid entries
			}
			latencies = append(latencies, latency)
		}
	}

	// If no individual times found, try to parse summary statistics
	if len(latencies) == 0 {
		// Try to find rtt min/avg/max/mdev line
		rttRe := regexp.MustCompile(`rtt\s+min/avg/max/mdev\s*=\s*\d+\.?\d*/(\d+\.?\d*)/\d+\.?\d*/\d+\.?\d*\s*ms`)
		rttMatches := rttRe.FindStringSubmatch(output)
		if len(rttMatches) >= 2 {
			avg, err := strconv.ParseFloat(rttMatches[1], 64)
			if err == nil {
				// Return the average as a single value for consistency
				return []float64{avg}, nil
			}
		}
	}

	return latencies, nil
}

func main() {
