		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command
	// -c: count of packets to send
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w, output: %s", err, string(output))
	}

	// Parse the output to extract RTT statistics
	// Typical Linux ping summary line:
	// rtt min/avg/max/mdev = 0.025/0.030/0.035/0.003 ms
	// We need to extract the avg value.

