		match = reMac.FindStringSubmatch(string(output))
		if len(match) < 2 {
			return 0, fmt.Errorf("could not parse ping output: %s", string(output))
		}
	}

	avgStr := match[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
