func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command
	// -c: count of packets to send
	// We use the standard ping command available on most Unix-like systems
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %w, output: %s", err, string(output))
	}

	// Parse the output to extract round-trip time statistics
	// Typical ping output ends with something like:
	// rtt min/avg/max/mdev = 10.123/15.456/20.789/2.345 ms
	// or on some systems:
	// round-trip min/avg/max/stddev = 10.123/15.456/20.789/2.345 ms

	outputStr := string(output)

	// Look for the line containing avg/average latency
	re := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(outputStr)

	if len(matches) < 2 {
		// Try alternative pattern for different ping implementations
		reAlt := regexp.MustCompile(`avg\s*=\s*([\d.]+)`)
		matchesAlt := reAlt.FindStringSubmatch(outputStr)
		if len(matchesAlt) >= 2 {
			avgStr := matchesAlt[1]
			avg, parseErr := strconv.ParseFloat(avgStr, 64)
			if parseErr != nil {
				return 0, fmt.Errorf("failed to parse average latency: %w", parseErr)
			}
			return avg, nil
		}

		// If we can't find the summary, try to parse individual ping times
		return parseIndividualPings(outputStr, count)
	}

