	return avg, nil
}

// parseIndividualPings parses individual ping response times when summary is not available
func parseIndividualPings(output string, expectedCount int) (float64, error) {
	// Match lines like: 64 bytes from ...: icmp_seq=1 ttl=64 time=10.123 ms
	re := regexp.MustCompile(`time=([\d.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(output, -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no ping responses found in output")
	}

	var total float64
	count := 0
	for _, match := range matches {
		if len(match) >= 2 {
			t, err := strconv.ParseFloat(match[1], 64)
			if err == nil {
				total += t
				count++
			}
		}
	}

	if count == 0 {
		return 0, fmt.Errorf("could not parse any ping times")
	}

	return total / float64(count), nil
}

