package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings the specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute the ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %w, output: %s", err, string(output))
	}

	// Parse the output to extract individual ping times
	lines := strings.Split(string(output), "\n")
	var totalLatency float64
	var validPings int

	// Regex to match lines like: "64 bytes from ... time=XX.XX ms"
	re := regexp.MustCompile(`time=(\d+\.?\d*)\s*ms`)

	for _, line := range lines {
		matches := re.FindStringSubmatch(line)
		if len(matches) >= 2 {
			latency, parseErr := strconv.ParseFloat(matches[1], 64)
			if parseErr != nil {
				continue
			}
			totalLatency += latency
			validPings++
		}
	}

	if validPings == 0 {
		return 0, fmt.Errorf("no valid ping responses received")
	}

	averageLatency := totalLatency / float64(validPings)
	return averageLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 3

	fmt.Printf("Measuring latency for host: %s, count: %d\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}
	fmt.Printf("Average Latency: %.2f ms\n", avgLatency)
}

