	}

	return parsePingOutput(string(output))
}

// parsePingOutput parses the ping command output to extract the average latency.
func parsePingOutput(output string) (float64, error) {
	// The ping output format varies by OS. This implementation targets Linux/macOS style output.
	// Example line: "rtt min/avg/max/mdev = 1.234/5.678/9.012/1.234 ms"
	re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := re.FindStringSubmatch(output)
	if len(matches) < 2 {
		// Try alternative format for some systems or if no packets were received
		// Check if there's an error message indicating failure
		if strings.Contains(output, "100% packet loss") || strings.Contains(output, "unknown host") {
			return 0, fmt.Errorf("no response from host")
		}
		return 0, fmt.Errorf("could not parse ping output: %s", output)
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %w", err)
	}

	return avg, nil
}

