import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command with the specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %v, output: %s", err, string(output))
	}

	outputStr := string(output)

	// Parse the average latency from the ping output
	// The typical format on Linux is: rtt min/avg/max/mdev = X/X/X/X ms
	// On macOS it's similar: round-trip min/avg/max/stddev = X/X/X/X ms
	re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+`)
	matches := re.FindStringSubmatch(outputStr)

	if len(matches) < 2 {
		// Try macOS format
		reMac := regexp.MustCompile(`round-trip min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+`)
		matches = reMac.FindStringSubmatch(outputStr)
	}

	if len(matches) < 2 {
		// If we can't find the summary line, try to parse individual ping times and calculate average
		// Look for lines like "64 bytes from ... time=X.XX ms"
		timeRe := regexp.MustCompile(`time=([\d.]+)\s*ms`)
		timeMatches := timeRe.FindAllStringSubmatch(outputStr, -1)

		if len(timeMatches) == 0 {
			return 0, fmt.Errorf("could not parse ping output: %s", outputStr)
		}

		var total float64
		for _, m := range timeMatches {
			t, err := strconv.ParseFloat(m[1], 64)
			if err != nil {
				return 0, fmt.Errorf("failed to parse ping time: %v", err)
			}
			total += t
		}

		return total / float64(len(timeMatches)), nil
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency: %v", err)
	}

	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 3

	fmt.Printf("Pinging %s %d times...\n", host, count)

	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avgLatency)
}

