package main

import (
	"bufio"
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	// Execute the ping command
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w, output: %s", err, string(output))
	}

	// Parse the output to extract latencies
	latencies, err := parsePingOutput(string(output))
	if err != nil {
		return 0, fmt.Errorf("failed to parse ping output: %w", err)
	}

	if len(latencies) == 0 {
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	// Calculate average latency
	var total float64
	for _, l := range latencies {
		total += l
	}
	average := total / float64(len(latencies))

	return average, nil
}

// parsePingOutput extracts individual ping latencies from the ping command output.
func parsePingOutput(output string) ([]float64, error) {
	var latencies []float64

	// Regular expression to match lines with time=XX.XX ms
	re := regexp.MustCompile(`time=(\d+\.?\d*)`)

	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		line := scanner.Text()
		matches := re.FindStringSubmatch(line)
		if len(matches) > 1 {
			latencyStr := matches[1]
			latency, err := strconv.ParseFloat(latencyStr, 64)
			if err != nil {
				continue // Skip if parsing fails
			}
			latencies = append(latencies, latency)
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("error reading ping output: %w", err)
	}

	return latencies, nil
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

