package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a given number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Build the ping command
	// -c: count, number of packets to send
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)

	// Execute the command and capture output
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %v, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	// Typical ping output contains a line like:
	// rtt min/avg/max/mdev = 1.234/5.678/9.012/1.234 ms
	// We need to extract the avg value

	outputStr := string(output)
	lines := strings.Split(outputStr, "\n")

	var avgLatency float64
	found := false

	// Regex to match the statistics line with avg latency
	// Matches patterns like: rtt min/avg/max/mdev = 1.234/5.678/9.012/1.234 ms
	re := regexp.MustCompile(`rtt\s+min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)

	for _, line := range lines {
		matches := re.FindStringSubmatch(line)
		if len(matches) > 1 {
			avgStr := matches[1]
			avg, parseErr := strconv.ParseFloat(avgStr, 64)
			if parseErr != nil {
				return 0, fmt.Errorf("failed to parse average latency: %v", parseErr)
			}
			avgLatency = avg
			found = true
			break
		}
	}

	if !found {
		return 0, fmt.Errorf("could not find average latency in ping output:\n%s", outputStr)
	}

	return avgLatency, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avgLatency)
}

