package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	// Execute ping command with specified count
	cmd := exec.Command("ping", "-c", strconv.Itoa(count), host)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("ping failed: %w, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	// Typical ping output on Linux/macOS contains a line like:
	// rtt min/avg/max/mdev = 1.234/5.678/9.012/0.345 ms
	// or on macOS: round-trip min/avg/max/stddev = 1.234/5.678/9.012/0.345 ms

	outputStr := string(output)

	// Try to find the avg value using regex
	// Pattern matches: avg=VALUE or /VALUE/ where VALUE is the average
	re := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/`)
	matches := re.FindStringSubmatch(outputStr)

	if len(matches) < 2 {
		// Try alternative pattern for macOS
		re = regexp.MustCompile(`round-trip min/avg/max/stddev\s*=\s*[\d.]+/([\d.]+)/`)
		matches = re.FindStringSubmatch(outputStr)
	}

	if len(matches) < 2 {
		// Try another common format
		re = regexp.MustCompile(`avg\s*=\s*([\d.]+)`)
		matches = re.FindStringSubmatch(outputStr)
	}

	if len(matches) < 2 {
		return 0, fmt.Errorf("could not parse average latency from ping output: %s", outputStr)
	}

	avgStr := matches[1]
	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to parse average latency value '%s': %w", avgStr, err)
	}

	return avg, nil
}

func main() {
	host := "localhost"
	count := 3

	if len(os.Args) > 1 {
		host = os.Args[1]
	}
	if len(os.Args) > 2 {
		c, err := strconv.Atoi(os.Args[2])
		if err == nil && c > 0 {
			count = c
		}
	}

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
}

