// MeasureLatency pings a specified host a user-defined number of times and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be positive")
	}

	// Build the ping command
	// On Linux: ping -c <count> <host>
	// On macOS: ping -c <count> <host>
	// On Windows: ping -n <count> <host>
	var cmd *exec.Cmd
	cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping command: %w, output: %s", err, string(output))
	}

	// Parse the output to extract average latency
	// Example output from Linux/macOS:
	// rtt min/avg/max/mdev = 10.123/15.456/20.789/3.456 ms
	// Example output from Windows:
	// Average = 15ms

	outputStr := string(output)

	// Try to parse Linux/macOS style output first
	reLinux := regexp.MustCompile(`rtt min/avg/max/mdev\s*=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	matches := reLinux.FindStringSubmatch(outputStr)
	if len(matches) > 1 {
		avgStr := matches[1]
		avg, err := strconv.ParseFloat(avgStr, 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Try to parse Windows style output
	reWindows := regexp.MustCompile(`Average\s*=\s*(\d+)ms`)
	matches = reWindows.FindStringSubmatch(outputStr)
	if len(matches) > 1 {
		avgStr := matches[1]
		avg, err := strconv.ParseFloat(avgStr, 64)
		if err != nil {
			return 0, fmt.Errorf("failed to parse average latency: %w", err)
		}
		return avg, nil
	}

	// Alternative parsing: look for "time=" or "time<" patterns and calculate average manually
	// This is more robust across different ping implementations
	timeRe := regexp.MustCompile(`time[=<](\d+(?:\.\d+)?)\s*ms`)
	allMatches := timeRe.FindAllStringSubmatch(outputStr, -1)
	if len(allMatches) == 0 {
		return 0, fmt.Errorf("could not parse latency from ping output:\n%s", outputStr)
	}

	var total float64
	for _, match := range allMatches {
		if len(match) > 1 {
			val, err := strconv.ParseFloat(match[1], 64)
			if err != nil {
				continue
			}
			total += val
		}
	}

	if len(allMatches) == 0 {
		return 0, fmt.Errorf("no valid latency values found in ping output")
	}

	average := total / float64(len(allMatches))
	return average, nil
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avgLatency)
}

